import{_ as a,o as n,a as p,b as l}from"./app.C56HXsMI.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据结构(TensorAPI，试验特性)","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/data_structure_TensorAPI"},{"text":"Tensor数据结构","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/tensor_structure"},{"text":"Slice","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/Slice"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/Slice.md","filePath":"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/Slice.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1785845486000}'),c={name:"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/Slice.md"};function t(e,s,i,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>Slice</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为试验接口，在后续版本中可能会调整或改进，不保证后续兼容性。请开发者在使用过程中关注后续版本更新。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>需要包含的头文件为：#include &quot;tensor_api/tensor.h&quot;。</p><p>Slice用于从张量指定坐标处切出一个子张量。根据输入的起始坐标coord和切片描述信息info，计算新的起始存储位置，并构造对应的子张量，子张量保持与原张量相同的存储位置类型。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Tensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Coord</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Info</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">decltype</span><span class="p">(</span><span class="k">auto</span><span class="p">)</span><span class="w"> </span><span class="n">Slice</span><span class="p">(</span><span class="n">Tensor</span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="n">tensor</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Coord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Info</span><span class="o">&amp;</span><span class="w"> </span><span class="n">info</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>Tensor</td><td>输入</td><td>张量类型，通常为GlobalTensor&lt;...&gt;或LocalTensor&lt;...&gt;。</td></tr><tr><td>Coord</td><td>输入</td><td>坐标类型，通常为Coord&lt;...&gt;元组类型。</td></tr><tr><td>Info</td><td>输入</td><td>切片描述类型，可以为Shape类型或Layout类型。传入Shape时，表示按给定形状截取子张量；传入Layout时，表示按Layout中的Shape信息截取子张量并保持原有布局模式和Stride结构。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>tensor</td><td>输入</td><td>待切片的张量对象。</td></tr><tr><td>coord</td><td>输入</td><td>切片起始坐标。</td></tr><tr><td>info</td><td>输入</td><td>切片描述信息。可以传入Shape或Layout。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回从coord指定位置开始的子张量对象。返回结果包含新的Layout信息，Engine指向切片后的起始位置。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>coord的tuple结构必须与当前Tensor的Layout.Shape()结构一致。</li><li>当info为Shape时：info必须是二维Shape；当前Tensor的Layout必须为二维或四维。</li><li>当info为Layout时，info必须与当前Tensor的Layout的维度相同。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">AscendC</span><span class="o">::</span><span class="nn">Te</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">gmAddr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>

<span class="c1">// 示例1：按Shape切片</span>
<span class="k">auto</span><span class="w"> </span><span class="n">layout1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeLayout</span><span class="p">(</span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">10</span><span class="p">,</span><span class="w"> </span><span class="mi">20</span><span class="p">),</span><span class="w"> </span><span class="n">MakeStride</span><span class="p">(</span><span class="mi">20</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">tensor1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">gmAddr</span><span class="p">),</span><span class="w"> </span><span class="n">layout1</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">sub1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">Slice</span><span class="p">(</span><span class="n">tensor1</span><span class="p">,</span><span class="w"> </span><span class="n">MakeCoord</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">4</span><span class="p">),</span><span class="w"> </span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">));</span>
<span class="c1">// 起始坐标为(2, 4)，子张量形状为(4, 8)</span>

<span class="c1">// 示例2：按Layout切片</span>
<span class="k">auto</span><span class="w"> </span><span class="n">layout2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeLayout</span><span class="p">(</span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">10</span><span class="p">,</span><span class="w"> </span><span class="mi">20</span><span class="p">),</span><span class="w"> </span><span class="n">MakeStride</span><span class="p">(</span><span class="mi">20</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">tensor2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">gmAddr</span><span class="p">),</span><span class="w"> </span><span class="n">layout2</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">sub2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">Slice</span><span class="p">(</span><span class="n">tensor2</span><span class="p">,</span><span class="w"> </span><span class="n">MakeCoord</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">),</span><span class="w"> </span><span class="n">MakeLayout</span><span class="p">(</span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">3</span><span class="p">,</span><span class="w"> </span><span class="mi">5</span><span class="p">),</span><span class="w"> </span><span class="n">MakeStride</span><span class="p">(</span><span class="mi">20</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">)));</span>
<span class="c1">// 从(1, 2)开始切出一个Shape为(3, 5)的子张量，并保持Stride结构</span>

<span class="c1">// 示例3：等价于调用成员函数</span>
<span class="k">auto</span><span class="w"> </span><span class="n">sub3</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tensor2</span><span class="p">.</span><span class="n">Slice</span><span class="p">(</span><span class="n">MakeCoord</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">),</span><span class="w"> </span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">3</span><span class="p">,</span><span class="w"> </span><span class="mi">5</span><span class="p">));</span>
<span class="c1">// sub3与Slice(tensor2, MakeCoord(1, 2), MakeShape(3, 5))等价</span>
</code></pre></div></article></div>`,1)])])}const w=a(c,[["render",t]]);export{u as __pageData,w as default};
